{"content": "/**
 * dsh-archive-watch —— DSH 宿主插件：每轮对话结束后自动归档会话日志。
 *
 * 为什么需要它
 *   助手的一条回复是在「本轮最后一次工具调用之后」才生成的，所以回合内跑的归档
 *   抓不到最后那条回复；两个回合之间若没有任何东西在运行，这段内容就一直缺着。
 *   原来的做法是手动启动 code/tools/archive-watch.ps1 这个外部常驻进程，
 *   每次重启 GUI 都要重新拉一次。本插件把那件事搬进 DSH 进程内部：
 *   宿主组合里的一行插件，随 GUI 启动自动生效，不需要任何手动启动。
 *
 * 它怎么工作（两个触发器，都汇入同一个 run()）
 *   1) 事件驱动：监听宿主的 `session/event`（提交后的追加事件流）。
 *      每轮回复落盘时都会经过这里；等到事件静默 quietSeconds 秒，
 *      说明这一轮说完了，立刻归档 —— 这才是「每轮对话后归档」。
 *   2) 兜底轮询：即使一个事件都没收到，每 safetySeconds 秒也检查一次
 *      会话日志的时间戳/文件数，变了就归档。事件监听万一失效也不会漏。
 *
 * 为什么是宿主平面而不是 agent preset
 *   归档守护必须整个进程只有一份、且跨会话共享（它归档的是所有会话）。
 *   放进 preset 会变成每个会话各起一份，既浪费又会互相争抢写入。
 *
 * 它做什么
 *   对每个配置的工作区，用 node 跑该工作区的归档脚本（默认
 *   code/tools/dsh-archive.mjs）：脚本自身零依赖、幂等、永远退出码 0，
 *   且只在会话日志真的变化时重写 prompt/ 下的产物。
 *   插件自己只负责「何时跑」，不重复实现归档逻辑。
 *
 * 日志
 *   追加到各工作区的 prompt/.archive-watch.log，格式与原来的
 *   archive-watch.ps1 一致，因此 AGENTS.md 里「看日志最后几行判断守护是否活着」
 *   的检查方式继续有效。没有更新时不写日志，避免刷屏（超过 512KB 自动留尾部 500 行）。
 *
 * 依赖：仅 Node 内置模块。不导出 Config（cordis 在没有 Config 时把行配置原样传入），
 * 因此本包不需要自带 node_modules，用 link: 安装即可。
 */

import { spawn } from 'node:child_process'
import { appendFileSync, existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { dirname, join, resolve } from 'node:path'

/** 稳定 cordis 插件名（与 cordis.patch.yml 里的行 id 一致，便于排查）。 */
export const name = 'archive-watch'

/** 不依赖任何服务：缺少服务会激活失败，而本插件用不到服务，必须随进程启动即生效。 */
export const inject = []

/** 行配置缺省值。 */
const DEFAULTS = {
  workspaces: [],
  archiver: 'code/tools/dsh-archive.mjs',
  logFile: 'prompt/.archive-watch.log',
  quietSeconds: 3,
  tickSeconds: 1,
  safetySeconds: 60,
  minSeconds: 5,
  bootSeconds: 3,
  maxArchiveSeconds: 180,
  logMaxBytes: 512 * 1024,
}

/** 输出摘要最多留这么多字符（够定位问题，不会把日志撑爆）。 */
const OUTPUT_TAIL_CHARS = 65536

/**
 * 挂载入口。任何异常都只记一条警告，绝不让归档插件影响 DSH 启动。
 * @param ctx - 宿主插件上下文。
 * @param config - cordis.patch.yml 里该行的 config。
 */
export function apply(ctx, config) {
  try {
    start(ctx, config ?? {})
  } catch (error) {
    warn(ctx, `挂载失败：${describe(error)}`)
  }
}

/** 记一条插件级警告到宿主日志（不写工作区日志，避免在挂载失败时反复创建目录）。 */
function warn(ctx, message) {
  try {
    ctx.logger?.warn?.(`archive-watch: ${message}`)
  } catch { /* 日志本身失败就算了 */ }
}

/** 把任意抛出物渲染成一行文本。 */
function describe(error) {
  if (error === undefined || error === null) return String(error)
  return String(error.stack ?? error.message ?? error)
}

/** 单行摘要（日志里只放第一行，堆栈放宿主日志）。 */
function firstLine(text) {
  const line = String(text).trim().split(/\r?\n/, 1)[0] ?? ''
  return line.length > 400 ? `${line.slice(0, 400)}…` : line
}

/** 本地时间 `yyyy-MM-dd HH:mm:ss`。 */
function localStamp(date) {
  const pad = (value) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} `
    + `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
}

/** 路径比较用的规范化形式（Windows 下大小写与分隔符都不敏感）。 */
function samePath(left, right) {
  try {
    return resolve(left).replace(/[\\/]+$/, '').toLowerCase()
      === resolve(right).replace(/[\\/]+$/, '').toLowerCase()
  } catch {
    return false
  }
}

/** DSH 会话日志根目录。 */
function sessionsRoot() {
  const home = process.env.DSH_HOME && process.env.DSH_HOME.trim() ? process.env.DSH_HOME : join(homedir(), '.dsh')
  return join(home, 'sessions')
}

/**
 * 扫描会话日志树，得到一个「有没有变化」的指纹（文件数 + 最新 mtime）。
 * 只有 2 层目录、几十个文件，成本可忽略；比直接跑一次归档进程便宜得多。
 */
function scanStamp(root) {
  let latest = 0
  let count = 0
  const walk = (dir, depth) => {
    let entries
    try {
      entries = readdirSync(dir, { withFileTypes: true })
    } catch {
      return
    }
    for (const entry of entries) {
      const full = join(dir, entry.name)
      if (entry.isDirectory()) {
        if (depth < 4) walk(full, depth + 1)
      } else if (entry.isFile()) {
        count++
        try {
          const info = statSync(full)
          if (info.mtimeMs > latest) latest = info.mtimeMs
        } catch { /* 正在被写入的文件忽略 */ }
      }
    }
  }
  walk(root, 0)
  return `${count}:${Math.round(latest)}`
}

/**
 * 启动归档循环。
 * @param ctx - 宿主插件上下文。
 * @param rawConfig - 行配置（未校验，全部在此归一化）。
 */
function start(ctx, rawConfig) {
  const cfg = { ...DEFAULTS, ...rawConfig }
  const rawWorkspaces = Array.isArray(cfg.workspaces) ? cfg.workspaces : [cfg.workspaces]
  const targets = rawWorkspaces
    .filter((item) => typeof item === 'string' && item.trim() !== '')
    .map((item) => resolve(item.trim()))

  if (targets.length === 0) {
    warn(ctx, '未配置 workspaces，插件不做事')
    return
  }

  const quietMs = Math.max(0, Number(cfg.quietSeconds) || 0) * 1000
  const tickMs = Math.max(200, (Number(cfg.tickSeconds) || 1) * 1000)
  const safetyMs = Math.max(1000, (Number(cfg.safetySeconds) || 60) * 1000)
  const minMs = Math.max(0, Number(cfg.minSeconds) || 0) * 1000
  const bootMs = Math.max(0, Number(cfg.bootSeconds) || 0) * 1000
  const maxArchiveMs = Math.max(1000, (Number(cfg.maxArchiveSeconds) || 180) * 1000)
  const logFile = typeof cfg.logFile === 'string' && cfg.logFile.trim() !== '' ? cfg.logFile.trim() : DEFAULTS.logFile
  const archiver = typeof cfg.archiver === 'string' && cfg.archiver.trim() !== '' ? cfg.archiver.trim() : DEFAULTS.archiver
  const logMaxBytes = Number(cfg.logMaxBytes) || DEFAULTS.logMaxBytes
  const root = sessionsRoot()

  /** 正在跑的归档子进程，卸载时全部收掉。 */
  const children = new Set()
  let lastEventAt = 0
  let lastRunAt = 0
  let lastStamp = ''
  let dirty = false
  let running = false
  let queued = false
  let runCount = 0
  let disposed = false

  /** 追加一行守护日志（必要时留尾部 500 行）。 */
  function logLine(target, message) {
    try {
      const file = join(target, logFile)
      mkdirSync(dirname(file), { recursive: true })
      appendFileSync(file, `[${localStamp(new Date())}] ${message}\n`, 'utf8')
      if (statSync(file).size <= logMaxBytes) return
      const kept = readFileSync(file, 'utf8').split(/\r?\n/).slice(-500).join('\n')
      writeFileSync(file, kept, 'utf8')
    } catch { /* 日志失败不影响归档 */ }
  }

  /** 跑一个工作区的归档脚本，把结果写进守护日志。 */
  function archiveWorkspace(target, reason) {
    return new Promise((done) => {
      const script = join(target, archiver)
      if (!existsSync(script)) {
        logLine(target, `跳过：找不到归档脚本 ${script}`)
        done()
        return
      }
      const startedAt = Date.now()
      let child
      try {
        child = spawn(process.execPath, [script, '--workspace', target], {
          cwd: target,
          windowsHide: true,
          stdio: ['ignore', 'pipe', 'pipe'],
          env: process.env,
        })
      } catch (error) {
        logLine(target, `归档进程启动失败：${firstLine(describe(error))}`)
        done()
        return
      }

      children.add(child)
      let stdout = ''
      let stderr = ''
      const keepTail = (current, chunk) => {
        const next = current + String(chunk)
        return next.length > OUTPUT_TAIL_CHARS ? next.slice(-OUTPUT_TAIL_CHARS) : next
      }
      child.stdout?.on('data', (chunk) => { stdout = keepTail(stdout, chunk) })
      child.stderr?.on('data', (chunk) => { stderr = keepTail(stderr, chunk) })

      const killer = setTimeout(() => {
        try { child.kill() } catch { /* 已经退出 */ }
      }, maxArchiveMs)

      const settle = (note) => {
        clearTimeout(killer)
        children.delete(child)
        if (disposed) { done(); return }
        const cost = Date.now() - startedAt
        const noise = stderr.trim()
        if (noise) logLine(target, `[warn] ${firstLine(noise)}`)
        const updated = /本次更新\s*(\d+)\s*个会话/.exec(stdout)
        const count = updated ? Number(updated[1]) : 0
        if (count > 0) {
          runCount++
          logLine(target, `已归档（触发：${note}，更新 ${count} 个会话，第 ${runCount} 次，耗时 ${cost}ms）`)
        } else if (note === 'boot') {
          logLine(target, `启动检查完成：暂无更新（耗时 ${cost}ms）`)
        } else if (note === 'timeout') {
          logLine(target, `[warn] 归档超时（${maxArchiveMs}ms）已中断`)
        }
        done()
      }

      child.on('error', (error) => {
        clearTimeout(killer)
        children.delete(child)
        logLine(target, `归档进程错误：${firstLine(describe(error))}`)
        done()
      })
      child.on('close', () => settle(reason))
    })
  }

  /**
   * 跑一轮归档。
   * @param reason - boot / event / safety / queued，只影响日志措辞与是否跳过。
   */
  async function run(reason) {
    if (disposed) return
    if (running) {
      queued = true
      return
    }
    running = true
    try {
      const before = scanStamp(root)
      // 兜底轮询：会话日志没有任何变化就不必起进程。
      if (reason === 'safety' && before === lastStamp) {
        lastRunAt = Date.now()
        return
      }
      for (const target of targets) {
        if (disposed) break
        await archiveWorkspace(target, reason)
      }
      lastStamp = scanStamp(root)
      lastRunAt = Date.now()
      if (reason === 'event') dirty = false
    } catch (error) {
      warn(ctx, `归档失败：${firstLine(describe(error))}`)
    } finally {
      running = false
      if (queued && !disposed) {
        queued = false
        setTimeout(() => { void run('queued') }, 0)
      }
    }
  }

  /** 每 tick 一次的内存判断，不做任何 IO。 */
  function tick() {
    if (disposed || running) return
    const now = Date.now()
    if (now - lastRunAt < minMs) return
    if (dirty && now - lastEventAt >= quietMs) {
      void run('event')
      return
    }
    if (now - lastRunAt >= safetyMs) void run('safety')
  }

  /** 会话事件：只对属于被守护工作区的会话置脏标记。 */
  function onSessionEvent(session) {
    try {
      const cwd = session?.header?.cwd
      if (typeof cwd === 'string' && cwd !== '' && !targets.some((target) => samePath(target, cwd))) return
    } catch { /* 读不到 cwd 就当作相关，宁可多跑一次 */ }
    lastEventAt = Date.now()
    dirty = true
  }

  ctx.effect(() => {
    const tickTimer = setInterval(tick, tickMs)
    const bootTimer = setTimeout(() => { void run('boot') }, bootMs)
    const offSessionEvent = ctx.on('session/event', onSessionEvent)

    for (const target of targets) {
      logLine(target, `archive-watch 插件已挂载：静默 ${quietMs / 1000}s / 兜底 ${safetyMs / 1000}s / 最小间隔 ${minMs / 1000}s`)
    }

    return () => {
      disposed = true
      clearInterval(tickTimer)
      clearTimeout(bootTimer)
      try { offSessionEvent() } catch { /* 已随 fiber 释放 */ }
      for (const child of children) {
        try { child.kill() } catch { /* 已经退出 */ }
      }
      children.clear()
    }
  }, 'archive-watch: 归档循环')
}
