{"content": "import { spawn } from 'node:child_process'
import { existsSync, rmSync } from 'node:fs'

const PROOF = 'E:/testPlatform/.spawn-proof.txt'
const CHILD = 'require("node:fs").writeFileSync("E:/testPlatform/.spawn-proof.txt","ok")'

function probe(label, stdio, script) {
  return new Promise((done) => {
    if (existsSync(PROOF)) rmSync(PROOF, { force: true })
    const events = []
    let child
    try {
      child = spawn(process.execPath, [script ? PROOF : '-e', script ? 'write' : CHILD], { stdio, windowsHide: true })
    } catch (error) {
      console.log(`${label}: spawn threw ${error.message}`)
      return done()
    }
    child.on('error', (error) => events.push(`error=${error.code ?? error.message}`))
    child.on('close', (code) => {
      events.push(`close=${code}`)
      console.log(`${label}: ${events.join(' ')} | 子进程是否真的跑完并写出文件: ${existsSync(PROOF) ? '是' : '否'}`)
      done()
    })
    child.stdout?.on('data', () => events.push('stdout'))
    child.stderr?.on('data', (c) => events.push(`stderr=${String(c).trim().slice(0, 120)}`))
  })
}

await probe('pipe stdio + node -e     ', ['ignore', 'pipe', 'pipe'], null)
await probe('ignore stdio + node -e   ', ['ignore', 'ignore', 'ignore'], null)
await probe('pipe stdio + 真归档脚本  ', ['ignore', 'pipe', 'pipe'], 'E:/testPlatform/code/tools/dsh-archive.mjs')
await probe('ignore stdio + 真归档脚本', ['ignore', 'ignore', 'ignore'], 'E:/testPlatform/code/tools/dsh-archive.mjs')
", "file_path": "E:\testPlatform\.spawn-probe.mjs"}

