{"content": "import { spawn } from 'node:child_process'
import { existsSync, rmSync, statSync } from 'node:fs'

const PROOF = 'E:/testPlatform/.spawn-proof.txt'
const INDEX = 'E:/testPlatform/prompt/INDEX.md'
const CHILD = 'require("node:fs").writeFileSync("E:/testPlatform/.spawn-proof.txt","ok")'
const ARCHIVER = 'E:/testPlatform/code/tools/dsh-archive.mjs'

function probe(label, stdio, args, verify) {
  return new Promise((done) => {
    const events = []
    const before = verify()
    let child
    try {
      child = spawn(process.execPath, args, { stdio, windowsHide: true })
    } catch (error) {
      console.log(`${label}: spawn threw ${error.message}`)
      return done()
    }
    child.stdout?.on('data', (c) => events.push(`stdout=${String(c).trim().slice(0, 90)}`))
    child.stderr?.on('data', (c) => events.push(`stderr=${String(c).trim().slice(0, 160)}`))
    child.on('error', (error) => events.push(`ERROR=${error.code ?? error.message}`))
    child.on('close', (code) => {
      events.push(`close=${code}`)
      console.log(`${label}: ${events.join(' | ')}`)
      console.log(`${label}: 验证判据 ${verify() !== before ? '通过（子进程真的跑了）' : '不通过（子进程没跑）'}`)
      done()
    })
  })
}

const nodeProof = () => {
  const value = existsSync(PROOF) ? statSync(PROOF).mtimeMs : 0
  return value
}
const archiverProof = () => (existsSync(INDEX) ? statSync(INDEX).mtimeMs : 0)
const cleanProof = () => { if (existsSync(PROOF)) rmSync(PROOF, { force: true }) }

await probe('pipe   + node -e      ', ['ignore', 'pipe', 'pipe'], ['-e', CHILD], nodeProof)
cleanProof()
await probe('ignore + node -e      ', ['ignore', 'ignore', 'ignore'], ['-e', CHILD], nodeProof)
await probe('inherit+ node -e      ', ['ignore', 'inherit', 'inherit'], ['-e', CHILD], nodeProof)
cleanProof()
await probe('pipe   + 归档脚本     ', ['ignore', 'pipe', 'pipe'], [ARCHIVER, '--workspace', 'E:/testPlatform'], archiverProof)
await probe('ignore + 归档脚本     ', ['ignore', 'ignore', 'ignore'], [ARCHIVER, '--workspace', 'E:/testPlatform'], archiverProof)
", "file_path": "E:\testPlatform\.spawn-probe.mjs"}

