import { readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

const dir = 'E:/testPlatform/prompt/原始事件'
for (const name of readdirSync(dir)) {
  if (!name.endsWith('.jsonl')) continue
  const lines = readFileSync(join(dir, name), 'utf8').split('\n').filter(Boolean)
  const tally = new Map()
  const samples = []
  for (const line of lines) {
    let event
    try { event = JSON.parse(line) } catch { continue }
    if (event.type !== 'user/message') continue
    const data = event.data ?? {}
    const message = data.message ?? data
    const source = message?.source
    const key = JSON.stringify(source ?? null)
    tally.set(key, (tally.get(key) ?? 0) + 1)
    if (samples.length < 4) {
      samples.push({
        topLevelKeys: Object.keys(data).join(','),
        hasMessageWrapper: data.message !== undefined,
        source,
        text: JSON.stringify(message?.content)?.slice(0, 110),
      })
    }
  }
  console.log(`\n########## ${name}  (user/message 共 ${[...tally.values()].reduce((a, b) => a + b, 0)} 条)`)
  for (const [key, count] of [...tally.entries()].sort((a, b) => b[1] - a[1])) {
    console.log(`  ${count.toString().padStart(3)} x source=${key}`)
  }
  for (const sample of samples) {
    console.log(`  - keys=[${sample.topLevelKeys}] wrapped=${sample.hasMessageWrapper} source=${JSON.stringify(sample.source)}`)
    console.log(`    text=${sample.text}`)
  }
}
