{"content": "// 临时探针：看清新 DSH 的 session.v4 是什么结构（跑完即删）。
import { readFileSync } from 'node:fs'
import { zstdDecompressSync } from 'node:zlib'

const DIR = 'C:/Users/sfy/.dsh/sessions/--E-testPlatform--'

/** 多帧 zstd 解码：一帧一个 JSONL 分片，拼起来即是事件流。 */
function decodeFrames(file) {
  const bytes = readFileSync(file)
  const parts = []
  let offset = 0
  while (offset < bytes.length) {
    try {
      const out = zstdDecompressSync(bytes.subarray(offset))
      parts.push(out.toString('utf8'))
      // 找出这一帧消耗了多少字节：从剩余缓冲里逐个试探代价太高，
      // 这里用「解压结果是否已包含到末尾」不可靠，改用 zstd 帧头扫描。
      const consumed = frameLength(bytes, offset)
      if (!consumed) break
      offset += consumed
    } catch (error) {
      console.log(`  解码在第 ${offset} 字节失败：${error.message}`)
      break
    }
  }
  return parts.join('')
}

/** 扫描 zstd 魔数与帧头算出单帧长度（含可选 content checksum）。 */
function frameLength(bytes, start) {
  if (bytes[start] !== 0x28 || bytes[start + 1] !== 0xb5 || bytes[start + 2] !== 0x2f || bytes[start + 3] !== 0xfd) return 0
  const fhd = bytes[start + 4]
  const fcsFlag = fhd >> 6
  const singleSegment = (fhd >> 5) & 1
  const hasChecksum = (fhd >> 2) & 1
  const didFlag = fhd & 3
  let pos = start + 5
  if (!singleSegment) pos += 1
  pos += [0, 1, 2, 4][didFlag]
  pos += [singleSegment ? 1 : 0, 2, 4, 8][fcsFlag]
  for (;;) {
    if (pos + 3 > bytes.length) return 0
    const bh = bytes[pos] | (bytes[pos + 1] << 8) | (bytes[pos + 2] << 16)
    const lastBlock = bh & 1
    const blockType = (bh >> 1) & 3
    const blockSize = bh >> 3
    pos += 3
    pos += blockType === 1 ? 1 : blockSize
    if (lastBlock) break
  }
  if (hasChecksum) pos += 4
  return pos - start
}

for (const [label, name] of [['v3', 'session.v3.jsonl.zstd'], ['v4', 'session.v4.jsonl.zstd']]) {
  const file = `${DIR}/session-76dc6050-a73c-4fa8-b9ec-f717b5f7c6d8/${name}`
  console.log(`\n================ ${label}：${file}`)
  try {
    const text = decodeFrames(file)
    const lines = text.split('\n').filter(Boolean)
    console.log(`解码字符数=${text.length}  行数=${lines.length}`)
    const events = lines.map((l) => { try { return JSON.parse(l) } catch { return null } }).filter(Boolean)
