}

function decodeFrames(path) {
  const bytes = readFileSync(path)
  const parts = []
  let offset = 0
  while (offset < bytes.length) {
    try {
      parts.push(zstdDecompressSync(bytes.subarray(offset)).toString('utf8'))
      const len = frameLength(bytes, offset)
      if (!len) break
      offset += len
    } catch { break }
  }
  return parts.join('')
}
function frameLength(bytes, start) {
  if (bytes[start] !== 0x28 || bytes[start + 1] !== 0xb5 || bytes[start + 2] !== 0x2f || bytes[start + 3] !== 0xfd) return 0
  const fhd = bytes[start + 4]
  const fcsFlag = fhd >> 6
  const singleSegment = (fhd >> 5) & 1
  const hasChecksum = (fhd >> 2) & 1
  const didFlag = fhd & 3
  let pos = start + 5
  if (!singleSegment) pos += 1
  pos += [0, 1, 2, 4][didFlag]
  pos += [singleSegment ? 1 : 0, 2, 4, 8][fcsFlag]
  for (;;) {
    if (pos + 3 > bytes.length) return 0
    const bh = bytes[pos] | (bytes[pos + 1] << 8) | (bytes[pos + 2] << 16)
    const last = bh & 1
    const type = (bh >> 1) & 3
    const size = bh >> 3
    pos += 3
    pos += type === 1 ? 1 : size
    if (last) break
  }
  if (hasChecksum) pos += 4
  return pos - start
}
